def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            colors = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            # Nested bands are ordered outer-to-inner by their bounding-box area.
            boxes = {}
            for color in colors:
                pts = [(y, x) for y, x in cells if grid[y][x] == color]
                boxes[color] = (max(y for y, x in pts) - min(y for y, x in pts) + 1) * (max(x for y, x in pts) - min(x for y, x in pts) + 1)
            layers = sorted(colors, key=lambda color: (-boxes[color], color))
            mapping = {color: layers[len(layers) - 1 - i] for i, color in enumerate(layers)}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
